import{_t as e,it as t,n,rt as r}from"./chunks/framework.CzjeapJW.js";var i=JSON.parse(`{"title":"Agents","description":"","frontmatter":{},"headers":[],"relativePath":"agents.md","filePath":"agents.md"}`),a={name:`agents.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="agents" tabindex="-1" dir="auto">Agents <a class="header-anchor" href="#agents" aria-label="Permalink to “Agents”">​</a></h1><blockquote dir="auto"><p dir="auto">Instinct&#39;s role as a PR reviewer is <strong>unverified</strong>. Everything else on this page is confirmed by the owner or by this repo.</p></blockquote><p dir="auto">Who does what in this repo. Three kinds of agent work on it:</p><ul><li dir="auto"><strong>Pipeline agents</strong> are defined in this repo. GitHub Actions workflows start them from issue labels, and deterministic jobs check what they produce. See <a href="./pipeline.html">pipeline.md</a>.</li><li dir="auto"><strong>Expert bots</strong> run outside the repo, in the owner&#39;s Grok Bot workspace (a desktop assistant app). They work through normal issues and PRs.</li><li dir="auto"><strong>Slack agents</strong> run outside the repo, in the Slack workspace.</li></ul><p dir="auto">Nothing in <code>.github/</code>, <code>AGENTS.md</code> or <code>docs/</code> starts or configures the agents outside the repo.</p><p dir="auto">No agent can merge. A code owner&#39;s approval on a green PR (<code>ci</code>, <code>security</code> and <code>pipeline/gates</code>) is the only way into <code>main</code> (<a href="./pipeline-review.html#review-gates-and-dispositions">Review gates</a>).</p><h2 id="pipeline-agents-in-this-repo" tabindex="-1" dir="auto">Pipeline agents (in this repo) <a class="header-anchor" href="#pipeline-agents-in-this-repo" aria-label="Permalink to “Pipeline agents (in this repo)”">​</a></h2><h3 id="plan" tabindex="-1" dir="auto">Plan <a class="header-anchor" href="#plan" aria-label="Permalink to “Plan”">​</a></h3><ul><li dir="auto"><strong>Prompt:</strong> <code>.github/prompts/plan.md</code> (spec writer and tech lead, one run).</li><li dir="auto"><strong>Runs in:</strong> <code>plan.yml</code>, job <code>plan</code>, through <code>anthropics/claude-code-action</code> (Claude, <code>CLAUDE_CODE_OAUTH_TOKEN</code>), at most 40 turns.</li><li dir="auto"><strong>Trigger:</strong> <code>stage:qualified</code> added to an open issue (by a person, or by the router or <code>/restart qualified</code>).</li><li dir="auto"><strong>Tools:</strong> <code>Read</code>, <code>Glob</code>, <code>Grep</code> only. No shell, no edits, no web.</li><li dir="auto"><strong>Output:</strong> one JSON object (<code>--json-schema</code>) with a <code>spec</code> and a <code>plan</code>. The <code>publish</code> job posts them as two bot comments (<code>&lt;!-- pipeline:spec --&gt;</code>, <code>&lt;!-- pipeline:plan --&gt;</code>) and, if every <a href="./pipeline-running.html#spec-and-plan-auto-approval">auto-approval check</a> passes, sets <code>stage:planned</code>. Otherwise an outcome note and <code>stage:routing</code>.</li></ul><h3 id="develop" tabindex="-1" dir="auto">Develop <a class="header-anchor" href="#develop" aria-label="Permalink to “Develop”">​</a></h3><ul><li dir="auto"><strong>Prompt:</strong> <code>.github/prompts/develop.md</code>.</li><li dir="auto"><strong>Runs in:</strong> <code>develop.yml</code>, job <code>implement</code>, through <code>anthropics/claude-code-action</code> (Claude), at most 150 turns.</li><li dir="auto"><strong>Trigger:</strong> <code>stage:planned</code> added to an open issue.</li><li dir="auto"><strong>Tools:</strong> file edits, <code>pnpm</code>, local <code>git status/diff/log/add/commit</code>. No <code>git push</code>, <code>gh</code>, <code>curl</code>, <code>wget</code> or web.</li><li dir="auto"><strong>Output:</strong> commits on <code>issue-&lt;n&gt;-&lt;slug&gt;</code> plus JSON (<code>status</code>, <code>pr_title</code>, <code>pr_body</code>, <code>blocked_reason</code>, <code>problem</code>). The <code>publish</code> job checks the patch, pushes the branch and opens a <strong>draft PR</strong> (<code>Closes #n</code>, <code>stage:building</code>). A patch whose protected paths are all approvable is pushed with no PR and waits for the owner (<a href="./pipeline-protected-changes.html#protected-change-approval">Protected-change approval</a>).</li></ul><h3 id="claude-review" tabindex="-1" dir="auto">Claude review <a class="header-anchor" href="#claude-review" aria-label="Permalink to “Claude review”">​</a></h3><ul><li dir="auto"><strong>Prompt:</strong> <code>.github/prompts/review.md</code>.</li><li dir="auto"><strong>Runs in:</strong> <code>review.yml</code>, job <code>review</code>, through <code>anthropics/claude-code-action</code> (Claude), at most 60 turns, with a read-only token.</li><li dir="auto"><strong>Trigger:</strong> once per head commit of a pipeline PR, after <code>ci</code> succeeds. Manual and Dependabot PRs are skipped.</li><li dir="auto"><strong>Tools:</strong> <code>Read</code>, <code>Glob</code>, <code>Grep</code> only. It does not run <code>pnpm verify</code>.</li><li dir="auto"><strong>Output:</strong> at most 5 findings against the issue&#39;s spec and plan (requirement, test, correctness, security; never style). The <code>publish</code> job posts them as review threads (<code>R-&lt;n&gt;</code>) and records the run in the <code>pipeline/review</code> status. See <a href="./pipeline-review.html#claude-review">Claude review</a> and the ADR <a href="./decisions/2026-11-23-claude-review-stage.html">2026-11-23-claude-review-stage</a>.</li></ul><h3 id="copilot-review-optional" tabindex="-1" dir="auto">Copilot review (optional) <a class="header-anchor" href="#copilot-review-optional" aria-label="Permalink to “Copilot review (optional)”">​</a></h3><ul><li dir="auto"><strong>Runs in:</strong> <code>approval.yml</code> requests it; GitHub Copilot code review writes it.</li><li dir="auto"><strong>Trigger:</strong> only when the repo variable <code>REQUIRE_COPILOT</code> is exactly <code>true</code>, once per head commit, after CI is green and no thread is open. Off by default.</li><li dir="auto"><strong>Output:</strong> review threads (<code>C-&lt;n&gt;</code>). Each must be resolved or dispositioned by the owner (<code>/disposition</code>) before <code>pipeline/gates</code> passes. See <a href="./pipeline-review.html#copilot-review-is-optional">Copilot review is optional</a>.</li></ul><h3 id="router-brain-stub" tabindex="-1" dir="auto">Router brain (stub) <a class="header-anchor" href="#router-brain-stub" aria-label="Permalink to “Router brain (stub)”">​</a></h3><ul><li dir="auto"><strong>Code:</strong> <code>.github/scripts/router-external.mjs</code>, called by the <code>brain</code> job of <code>router.yml</code> (read-only token).</li><li dir="auto"><strong>Trigger:</strong> <code>stage:routing</code>, only when <code>ROUTER_MODE=external</code> or <code>ROUTER_SHADOW=true</code>.</li><li dir="auto"><strong>Today:</strong> it returns <code>null</code> and makes no network call, so the rules table decides every route. See <a href="./pipeline-router.html#router">Router</a>.</li></ul><p dir="auto">There is no automated fixing of review comments (ADR <a href="./decisions/2026-10-03-remove-gemini-stages.html">2026-10-03-remove-gemini-stages</a>).</p><h2 id="expert-bots-grok-bot-workspace" tabindex="-1" dir="auto">Expert bots (Grok Bot workspace) <a class="header-anchor" href="#expert-bots-grok-bot-workspace" aria-label="Permalink to “Expert bots (Grok Bot workspace)”">​</a></h2><p dir="auto">Each bot in the owner&#39;s Grok Bot workspace has its own chat, memory and routines, and the bots can message each other. The owner talks to them directly. They work on this repo only through normal GitHub issues and PRs, so their changes pass the same checks as anyone&#39;s, and a human merges.</p><table tabindex="0"><thead><tr><th dir="auto">Bot</th><th dir="auto">Owns</th></tr></thead><tbody><tr><td dir="auto"><code>site-expert</code></td><td dir="auto"><code>apps/site</code>: the Vite product app</td></tr><tr><td dir="auto"><code>e2e-expert</code></td><td dir="auto"><code>apps/site-e2e</code>: the Playwright tests for <code>site</code></td></tr><tr><td dir="auto"><code>pipeline-expert</code></td><td dir="auto">the CI and agent pipeline (<code>.github/workflows/</code>, scripts, prompts)</td></tr><tr><td dir="auto"><code>docs-expert</code></td><td dir="auto"><code>README.md</code>, <code>docs/</code>, and the explanations of the agents and pipeline</td></tr><tr><td dir="auto"><code>cleaner</code></td><td dir="auto">nothing in the repo: a meta-agent that audits which expert bots are used</td></tr></tbody></table><p dir="auto"><code>.github/**</code> is never approvable for the pipeline agents (<a href="https://github.com/menashsoffer/nx-ai-agents-workspace/blob/HEAD/AGENTS.md" target="_blank" rel="noreferrer">AGENTS.md</a>, &quot;Protected files&quot;), so <code>pipeline-expert</code>&#39;s changes there go through a normal PR that the owner reviews.</p><p dir="auto">The workspace also has bots that do not work on this repo; they are not listed here.</p><h2 id="slack-agents" tabindex="-1" dir="auto">Slack agents <a class="header-anchor" href="#slack-agents" aria-label="Permalink to “Slack agents”">​</a></h2><p dir="auto">They use the Slack workspace <strong>Do It</strong>, channel <strong>#ai</strong>. The Slack apps there are <strong>Instinct</strong>, <strong>Cursor</strong> (Cursor Cloud Agents, default repository <code>menashsoffer/nx-ai-agents-workspace</code>) and <strong>GitHub</strong> (GitHub for Slack).</p><h3 id="instinct" tabindex="-1" dir="auto">Instinct <a class="header-anchor" href="#instinct" aria-label="Permalink to “Instinct”">​</a></h3><ul><li dir="auto"><strong>What it is:</strong> a Slack bot app (<code>@Instinct</code>) in #ai.</li><li dir="auto"><strong>What it does:</strong> coordinates. It sends tasks to <code>@Cursor</code> in #ai threads (for example: split <code>pipeline-lib.mjs</code> for #99, harden <code>tools/pages/src/serve.mjs</code> for #120), asks <code>@Cursor</code> for agent status, and asks <code>@GitHub</code> for open PRs, issues and CI status. Code changes it asks for are done by Cursor agents on a new branch with a PR, never on <code>main</code>.</li><li dir="auto"><strong>Unverified:</strong> that Instinct <strong>reviews PRs</strong>. How a review is triggered, and where it lands (a PR review, a comment, or Slack only), is not recorded yet.</li><li dir="auto"><strong>Not a gate:</strong> <code>pipeline/gates</code> and the ruleset do not read anything Instinct writes. Its output counts only through the humans who act on it.</li></ul><h2 id="how-they-fit-together" tabindex="-1" dir="auto">How they fit together <a class="header-anchor" href="#how-they-fit-together" aria-label="Permalink to “How they fit together”">​</a></h2><ol><li dir="auto">Work starts as a GitHub issue (<code>[Task]</code> template). A person adds <code>stage:qualified</code>, and the pipeline agents take it from there (<a href="./pipeline-running.html#running-one-task-through-it">Running one task</a>).</li><li dir="auto">Outside the pipeline, an expert bot, Instinct (through <code>@Cursor</code>) or a person can open an issue or a PR directly. Such a PR is <strong>not</strong> a pipeline PR: no <code>stage:*</code> label, and the pipeline does not plan or develop it. An issue they open goes through the pipeline like any other.</li><li dir="auto">Every PR, from either source, needs the same checks: <code>ci</code>, <code>security</code> and <code>pipeline/gates</code> (CI green, every review thread resolved or dispositioned, protected changes approved). Then a code owner approves and merges.</li><li dir="auto">Expert bots and Slack agents have no special standing in the pipeline: a label, a comment or a review they post is treated like anyone&#39;s. Only notes by <code>PIPELINE_BOT_LOGIN</code> and commands by <code>PIPELINE_OWNER_LOGIN</code> count.</li></ol><h2 id="open-questions" tabindex="-1" dir="auto">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to “Open questions”">​</a></h2><ul><li dir="auto">Where Instinct&#39;s PR reviews appear, and whether the owner treats them as required before merging.</li></ul>`,31)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};